package com.hookdeveloper.catlive.remote;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.nio.charset.StandardCharsets;import java.io.*;import java.util.*;
public class RemoteContractTest {
 @Test public void gridHidesBpmMarkersWithoutHidingUnifiedSongs()throws Exception{
  JSONObject state=new JSONObject().put("timelineRegions",new JSONArray().put(new JSONObject().put("id","child").put("parentRegion","unified").put("name","TEMPO").put("start",12)));
  assertTrue(RemoteModel.gridTempoMarker(state,new JSONObject().put("name","140 BPM").put("tempoBPM",140)));
  assertTrue(RemoteModel.gridTempoMarker(state,new JSONObject().put("name","TEMPO").put("position",0)));
  assertFalse(RemoteModel.gridTempoMarker(state,new JSONObject().put("name","TEMPO").put("position",12)));
  assertFalse(RemoteModel.gridTempoMarker(state,new JSONObject().put("name","TEMPO").put("sourceRegionID","child")));
  assertFalse(RemoteModel.gridTempoMarker(state,new JSONObject().put("name","Refrão").put("section",true)));
  assertFalse(RemoteModel.gridTempoMarker(state,new JSONObject().put("name","Música 2").put("unifiedRegionID","unified")));
 }
 byte[] bytes(JSONObject f,String key)throws Exception{String hex=f.getString(key);byte[] b=new byte[hex.length()/2];for(int i=0;i<b.length;i++)b[i]=(byte)Integer.parseInt(hex.substring(i*2,i*2+2),16);return b;}
 JSONObject fixture()throws Exception{return new JSONObject(new String(getClass().getResourceAsStream("/remote-cipher.json").readAllBytes(),StandardCharsets.UTF_8));}
 RemoteCipher make(JSONObject f,boolean host)throws Exception{byte[] key=new byte[32];for(int i=0;i<32;i++)key[i]=(byte)(i+(host?1:100));byte[] hello=bytes(f,host?"hostHello":"clientHello");String name=new String(hello,37,hello.length-37,StandardCharsets.UTF_8);RemoteCipher c=new RemoteCipher(name,host,key);assertArrayEquals(hello,c.hello());c.accept(bytes(f,host?"clientHello":"hostHello"));return c;}
 @Test public void macWindowsCryptoFixture()throws Exception{JSONObject f=fixture();RemoteCipher host=make(f,true),client=make(f,false);assertArrayEquals(bytes(f,"hostReady"),host.seal(new byte[]{0}));assertArrayEquals(bytes(f,"clientReady"),client.seal(new byte[]{0}));assertArrayEquals(new byte[]{0},client.open(bytes(f,"hostReady")));assertArrayEquals(new byte[]{0},host.open(bytes(f,"clientReady")));assertArrayEquals(bytes(f,"hostPacket"),host.seal(bytes(f,"hostPlain")));assertArrayEquals(bytes(f,"clientPacket"),client.seal(bytes(f,"clientPlain")));assertArrayEquals(bytes(f,"hostPlain"),client.open(bytes(f,"hostPacket")));assertArrayEquals(bytes(f,"clientPlain"),host.open(bytes(f,"clientPacket")));}
 @Test public void refusesReplayAndCorruption()throws Exception{JSONObject f=fixture();RemoteCipher client=make(f,false);byte[] ready=bytes(f,"hostReady");byte[] broken=ready.clone();broken[broken.length-1]^=1;try{client.open(broken);fail();}catch(Exception expected){}assertArrayEquals(new byte[]{0},client.open(ready));try{client.open(ready);fail();}catch(Exception expected){}}
 @Test public void rejectsLengthsBeforeAllocation()throws Exception{for(int size:new int[]{0,-1,Integer.MAX_VALUE,RemoteCipher.MAX_FRAME+1}){byte[] header=java.nio.ByteBuffer.allocate(4).putInt(size).array();try{RemoteWire.readFrame(new ByteArrayInputStream(header));fail();}catch(Exception expected){}}}
 @Test public void fragmentedStreamAndMultipleFrames()throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();RemoteWire.writeFrame(out,new byte[]{1,2,3});RemoteWire.writeFrame(out,new byte[]{4});InputStream oneByte=new FilterInputStream(new ByteArrayInputStream(out.toByteArray())){public int read(byte[] b,int off,int len)throws IOException{return super.read(b,off,Math.min(1,len));}};assertArrayEquals(new byte[]{1,2,3},RemoteWire.readFrame(oneByte));assertArrayEquals(new byte[]{4},RemoteWire.readFrame(oneByte));}
 @Test public void stoppedNoticeCommandCarriesCapturedDraftAndSlot()throws Exception{
  JSONObject state=new JSONObject("{\"project\":\"A\",\"song\":\"B\"}");
  for(int slot=-1;slot<3;slot++){JSONObject c=RemoteWire.command(state,"noticePinStopped",null,slot,"Pausa 🎵",null,true);assertEquals(slot,c.getInt("value"));assertEquals("Pausa 🎵",c.getString("text"));assertTrue(c.getBoolean("enabled"));assertFalse(c.has("target"));}
  assertTrue(RemoteWire.allowed("noticePinStopped","notices",-1));assertTrue(RemoteWire.allowed("noticePinStopped","director",0));assertFalse(RemoteWire.allowed("noticePinStopped","observer",0));
 }
 @Test public void commandShapeAndObserverWhitelist()throws Exception{JSONObject s=new JSONObject("{\"project\":\"A\",\"song\":\"B\"}");JSONObject c=RemoteWire.command(s,"volume","TRACK",.707945784,null,null,null);assertEquals("A",c.getString("project"));assertEquals("B",c.getString("song"));assertEquals(.707945784,c.getDouble("value"),1e-9);assertFalse(RemoteWire.allowed("play","observer",0));assertFalse(RemoteWire.allowed("remotePanel","observer",3));assertTrue(RemoteWire.allowed("remotePanel","observer",2));assertTrue(RemoteWire.allowed("noticeSend","notices",-1));assertFalse(RemoteWire.allowed("mute","notices",0));}
 @Test public void faderDataMatchesDecibels(){assertEquals(0,RemoteModel.gain(-60),0);assertEquals(1,RemoteModel.gain(0),0);assertEquals(.7079457843841379,RemoteModel.gain(-3),1e-12);assertEquals(-3,RemoteModel.db(RemoteModel.gain(-3)),1e-12);}
 @Test public void duplicateOnlyBlocksSameMusic()throws Exception{JSONObject s=new JSONObject("{\"playing\":false,\"currentRegion\":\"A\",\"timelineRegions\":[{\"id\":\"A\"},{\"id\":\"B\"}]}");JSONObject alias=new JSONObject("{\"id\":\"ALIAS\",\"sourceRegionId\":\"A\"}");assertTrue(RemoteModel.canQueue(s,alias));s.put("playing",true);assertFalse(RemoteModel.canQueue(s,alias));s.put("currentRegion","B");assertTrue(RemoteModel.canQueue(s,alias));}
 @Test public void partsUsesConfirmedHostPosition()throws Exception{JSONObject s=new JSONObject("{\"project\":\"P\",\"playing\":true,\"position\":4,\"timelineRegions\":[{\"id\":\"R\",\"start\":0,\"end\":20}],\"markers\":[{\"id\":\"M\",\"section\":true,\"name\":\"Refrão\",\"position\":10}]}");RemoteModel.Cue cue=new RemoteModel.Cue();assertEquals("",cue.update(s,0));s.put("position",5);assertEquals("Refrão",cue.update(s,1));assertEquals("Refrão",cue.update(s,1800));s.put("position",10);assertEquals("",cue.update(s,1900));s.put("playing",false);assertEquals("",cue.update(s,2000));}
}
